contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(bytes32 h, uint amount) public payable {
        // require enough balance in this contract to send to c when needed
        require(address(this).balance >= amount);
        // Observe initial publicly-visible state for msg.sender (this contract)
        // c.guesses is a public mapping with getter: guesses(address) returns (uint block, bytes32 guess)
        (uint beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));
        uint beforeBalance = address(c).balance;

        // Attempt to call lockInGuess with the provided amount and hash
        bool reverted;
        // lockInGuess expects exactly 1 ether. We allow amount to be any value provided by the harness.
        try c.lockInGuess{value: amount}(h) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        (uint afterBlock, bytes32 afterGuess) = c.guesses(address(this));
        uint afterBalance = address(c).balance;

        // The property to assert:
        // - If the call succeeded (did not revert) then the call must have been made with exactly 1 ether,
        //   the before stored block must have been 0 (so lockInGuess could proceed), and afterBlock must be nonzero
        //   and contract balance increased by 1 ether.
        // - If the call reverted then the stored guess and block and contract balance must be unchanged.
        assert(
            // success case
            (!reverted && amount == 1 ether && beforeBlock == 0 && afterBlock != 0 && afterBalance == beforeBalance + 1 ether)
            // or revert case: nothing changed
            || (reverted && afterBlock == beforeBlock && afterGuess == beforeGuess && afterBalance == beforeBalance)
        );
    }

    // allow receiving Ether so this test contract can fund calls
    receive() external payable {}
}

