contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // h1,h2: two guess hashes to try; amount: Ether to send with each lockInGuess call
    function run(bytes32 h1, bytes32 h2, uint amount) public payable {
        // ensure this test contract has enough balance to forward `amount` twice
        require(address(this).balance >= amount * 2);
        // require amount is nonzero so comparisons meaningful (but not required by P)
        require(amount > 0);

        uint beforeBalance = address(c).balance;

        bool firstReverted;
        // Try the first lockInGuess call
        try c.lockInGuess{value: amount}(h1) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint midBalance = address(c).balance;

        bool secondReverted;
        // Try a second immediate lockInGuess call from the same caller
        try c.lockInGuess{value: amount}(h2) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint afterBalance = address(c).balance;

        // General rule asserted:
        // - If the first call succeeded, it must have been sent exactly 1 ether and increased c's balance by 1 ether,
        //   and then the immediate second call must revert (cannot lock twice).
        // - If the first call reverted, the contract balance must be unchanged (no Ether accepted).
        assert(
            ( !firstReverted
                && amount == 1 ether
                && midBalance == beforeBalance + 1 ether
                && secondReverted
                && afterBalance == midBalance
            )
            || (
                firstReverted
                && midBalance == beforeBalance
                && (secondReverted ? afterBalance == midBalance : afterBalance == midBalance + amount)
                // note: if first reverted then second might succeed only if amount==1 ether; we allow both
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We attempt to lock a guess and then call settle(); amount should be 1 ether to succeed in lockInGuess.
    // h: guess hash to lock; amount: Ether forwarded to lockInGuess; settleMayRevert parameter is unused but
    // kept to provide variation for the prover.
    function run(bytes32 h, uint amount, bool /*settleMayRevert*/) public payable {
        // only require that this contract has enough balance to forward `amount` (and keep some for safety)
        require(address(this).balance >= amount + 0);
        // record balances before any interactions
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;

        bool lockedReverted;
        // Try to lock a guess; this may revert (e.g., if amount != 1 ether)
        try c.lockInGuess{value: amount}(h) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // After attempting lockInGuess, attempt to call settle()
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;

        // General invariant to assert:
        // If settle succeeded and this contract's balance increased (we received 2 ether payout), then
        // (1) before calling settle the contract c must have had at least 2 ether (so it could pay), and
        // (2) we must previously have successfully locked a guess (i.e., lockInGuess did not revert) so that settle
        //     could operate on a stored guess for this caller.
        // Otherwise (if settle reverted or our balance did not increase) there is no requirement about c's prior balance.
        assert(
            (
                !settleReverted
                && afterMe > beforeMe
            )
            ->
            (
                !lockedReverted
                && beforeC >= 2 ether
            )
            || (
                settleReverted || afterMe == beforeMe
            )
        );
    }

    // helper to allow receiving Ether when c.transfer is used
    receive() external payable {}
}

