contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We accept two parameters: the hash to lock in and an amount to send when locking (must be 1 ether)
    // Also a flag callSettle indicates whether we attempt to call settle afterwards.
    function run(bytes32 h, uint lockAmount, bool callSettle) public payable {
        require(lockAmount == 1 ether);
        // Ensure this contract has enough balance to send
        require(address(this).balance >= lockAmount);

        // Before values: contract balances
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Attempt to lock in guess (should set guesses[msg.sender] and reserve 1 ether in the target)
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Read balance after lock attempt
        uint afterLockC = address(c).balance;
        uint afterLockThis = address(this).balance;

        // If lock did not revert, contract must have gained exactly 1 ether
        if (!lockReverted) {
            // Observables only: compare balances
            assert(afterLockC == beforeC + 1 ether);
            assert(afterLockThis == beforeThis - 1 ether);
        } else {
            // If it reverted, balances unchanged
            assert(afterLockC == beforeC);
            assert(afterLockThis == beforeThis);
        }

        // Optionally attempt settle once. We cannot control block progression here,
        // so settle might revert if called too early. Capture revert flag and balances.
        bool settleReverted = false;
        uint beforeSettleC = address(c).balance;
        uint beforeSettleThis = address(this).balance;
        if (callSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        }
        uint afterSettleC = address(c).balance;
        uint afterSettleThis = address(this).balance;

        // General rule (single assert):
        // If lockInGuess succeeded and settle was called and did NOT revert,
        // then either the contract transferred 2 ether to this contract (winning case) or it did not transfer (non-winning case).
        // When transfer happened, c's balance decreased by 2 ether and this contract's balance increased by 2 ether.
        // When transfer did not happen, balances are unchanged from beforeSettle.
        // If settle reverted or lock reverted, no unexpected balance movement occurred.
        assert(
            (
                // Case: lock reverted => no balances changed at any step
                lockReverted && afterLockC == beforeC && afterLockThis == beforeThis && (!callSettle || (settleReverted && afterSettleC == beforeSettleC && afterSettleThis == beforeSettleThis))
            ) || (
                // Case: lock succeeded but settle not called => afterLock balances observed, settle balances equal afterLock
                (!lockReverted && !callSettle && afterLockC == afterSettleC && afterLockThis == afterSettleThis)
            ) || (
                // Case: lock succeeded, settle called and reverted => balances unchanged from beforeSettle
                (!lockReverted && callSettle && settleReverted && afterSettleC == beforeSettleC && afterSettleThis == beforeSettleThis)
            ) || (
                // Case: lock succeeded, settle called and did not revert => either win (2 ether moved) or lose (no movement)
                (!lockReverted && callSettle && !settleReverted && (
                    (afterSettleC + 2 ether == beforeSettleC && afterSettleThis == beforeSettleThis + 2 ether) ||
                    (afterSettleC == beforeSettleC && afterSettleThis == beforeSettleThis)
                ))
            )
        );
    }

    receive() external payable {}
}

