        } catch {
            lockReverted = true;
        }

        // balances after lock attempt
        uint afterLockC = address(c).balance;
        uint afterLockThis = address(this).balance;

        // Optionally attempt settle as a top-level state-changing call and capture revert flag
        bool settleReverted = false;
        if (doSettle) {
            // record balances before settle
            uint beforeSettleC = address(c).balance;
            uint beforeSettleThis = address(this).balance;
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
            // balances after settle
            uint afterSettleC = address(c).balance;
            uint afterSettleThis = address(this).balance;

            // General assert covering all observable cases in terms of balances and revert flags
            assert(
                // If lock reverted, neither balances nor settle effects should have occurred
                (lockReverted && afterLockC == beforeC && afterLockThis == beforeThis && settleReverted && afterSettleC == beforeSettleC && afterSettleThis == beforeSettleThis)
                ||
                // If lock succeeded and we did not call settle, c gained exactly 1 ether and this lost 1 ether
                (!lockReverted && !doSettle && afterLockC == beforeC + 1 ether && afterLockThis == beforeThis - 1 ether)
                ||
                // If lock succeeded and settle reverted, then settle left balances unchanged from beforeSettle
                (!lockReverted && doSettle && settleReverted && afterLockC == beforeSettleC && afterLockThis == beforeSettleThis)
                ||
                // If lock succeeded and settle did not revert, then either settle paid out exactly 2 ether to this contract or did nothing
                (!lockReverted && doSettle && !settleReverted && (
                    // win: c lost 2 ether and this gained 2 ether relative to beforeSettle
                    (afterSettleC + 2 ether == beforeSettleC && afterSettleThis == beforeSettleThis + 2 ether)
                    ||
                    // lose: balances unchanged by settle
                    (afterSettleC == beforeSettleC && afterSettleThis == beforeSettleThis)
                ))
            );
            return;
        }

        // If we didn't call settle, assert the observable invariants after lock step
        assert(
            // If lock reverted, balances unchanged
            (lockReverted && afterLockC == beforeC && afterLockThis == beforeThis)
            ||
            // If lock succeeded, c gained exactly 1 ether and this lost 1 ether
            (!lockReverted && afterLockC == beforeC + 1 ether && afterLockThis == beforeThis - 1 ether)
        );
    }

    receive() external payable {}
}

