contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a guessed hash and an amount; amount must be exactly 1 ether to satisfy contract requirements.
    function run(bytes32 h, uint amount) public payable {
        require(amount == 1 ether);
        // ensure this contract has enough balance to send
        require(address(this).balance >= amount);

        // Before calling, read the stored guess struct for this address (auto getter for mapping isn't available, but C has no public getter for mapping; however the contract exposes no getter — instead we will observe effects via settle behavior and contract balance).
        // We attempt to lock in the guess and record whether it reverted.
        bool reverted;
        try c.lockInGuess{value: amount}(h) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After a successful lockInGuess, the contract should have accepted exactly 1 ether payment (so its balance increased by 1 ether), and the call should not have reverted.
        // We assert: if lockInGuess did not revert, then address(c).balance >= 1 ether and reverted==false.
        // Additionally, because lockInGuess sets the stored block to block.number+1, that stored block must be strictly greater than the current block number.
        // We cannot read the internal mapping directly, but the contract's settle requires guesses[msg.sender].block != 0 and block.number > storedBlock to proceed.
        // We can check that if lockInGuess succeeded then settle called immediately would revert because block.number is not greater than storedBlock (since storedBlock == current+1). So try settle and expect it to revert when lockInGuess succeeded.

        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // General rule: if lockInGuess succeeded then contract balance increased by at least 1 ether (observed now), and settle must revert when called immediately after (because stored block > current block).
        assert((reverted == false) == (address(c).balance >= 1 ether && settleReverted == true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params: a precomputed guess hash h and two amounts: amountLock must be 1 ether to call lockInGuess,
    // and fundInitial is how much Ether this test contract is funded with before sending to C.
    // The function is payable so the test harness can fund this contract when calling run.
    function run(bytes32 h, uint amountLock, uint fundInitial) public payable {
        // require that the caller provided enough value to cover our intended funding use
        require(msg.value == fundInitial);
        // amountLock must be exactly 1 ether to satisfy C.lockInGuess
        require(amountLock == 1 ether);
        // ensure this contract has the funds we will use to call C
        require(address(this).balance >= amountLock);

        // 1) Lock in a guess by sending 1 ether to c; record whether it reverted.
        bool lockReverted;
        try c.lockInGuess{value: amountLock}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // 2) Attempt to advance to settle: call settle and record whether it reverted.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // 3) Record balances observable externally
        uint balC = address(c).balance;
        uint balThis = address(this).balance;

        // General rule (single assert): If settle did NOT revert (i.e., it succeeded), then
        // a) the test contract must have received 2 ether from C (so its balance increased by 2 ether
        //    relative to after paying amountLock), and b) the settle call must have cleared the stored
        //    guess such that an immediate subsequent settle call will revert (because guesses[msg.sender].block == 0).
        // We observe (b) by calling settle again and expecting it to revert.
        bool secondSettleReverted;
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }

        // Note: Because we funded the contract with fundInitial and then paid amountLock to lockInGuess,
        // a successful settle should transfer 2 ether to this contract. To express that as an observable relation
        // without relying on intermediate snapshots, we require that if settle succeeded then balThis increased
        // by at least 1 ether compared to balC before settle? We can't read prior snapshots now, so instead we assert
        // that when settle succeeds, the contract's balance decreased by 2 ether relative to what it would have been
        // had lockInGuess alone succeeded. However, simpler and robust observable claim: after a successful settle,
        // address(this).balance is at least fundInitial - amountLock + 2 ether (i.e., we got back the stake plus reward).

        uint expectedMinBalanceAfterReward = fundInitial - amountLock + 2 ether;

        assert((settleReverted == false) == (balThis >= expectedMinBalanceAfterReward && secondSettleReverted == true));
    }

    receive() external payable {}
}

