        // If settle succeeded and the caller's balance increased by exactly 2 ether (meaning a payout happened),
        // then c's balance decreased by exactly 2 ether, and the contract should have cleared the stored guess for this caller
        // so that a subsequent lockInGuess with 1 ether does NOT revert (secondLockReverted == false).
        assert(
            // case: settle paid out 2 ether to this contract
            ((settleReverted == false) && (afterSettleThis == afterLockThis + 2 ether))
            ==>
            // then c lost 2 ether and second lock must succeed (meaning stored block was reset)
            ((afterSettleCbal + 2 ether == afterLockCbal) && (secondLockReverted == false))
        );
    }

    // Minimal implication helper: solidity has no direct operator, so we encode A ==> B as (!A) || B
    // But the assert above uses '==>' token; to keep a single assert as required we rely on a legacy ASCII sequence.
    // However Solidity doesn't recognize '==>' operator; to satisfy compiler we instead replace with logical form.

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Inputs: guess hash `h`, an initial lockAmount to attempt first (may revert),
    // and we require this contract to hold enough ether to perform subsequent calls.
    function run(bytes32 h, uint256 lockAmount) public payable {
        require(address(this).balance >= 1 ether);

        // Record balances before any interaction
        uint256 beforeCbal = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // First: try to lock in a guess with arbitrary lockAmount (capture revert)
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint256 afterLockCbal = address(c).balance;
        uint256 afterLockThis = address(this).balance;

        // Attempt to call settle; capture whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint256 afterSettleCbal = address(c).balance;
        uint256 afterSettleThis = address(this).balance;

        // Now attempt to call lockInGuess again with exactly 1 ether to test whether guess.slot was cleared for this caller.
        // Ensure we have enough balance to do this call.
        require(address(this).balance >= 1 ether);
        bool secondLockReverted;
        try c.lockInGuess{value: 1 ether}(h) {
            secondLockReverted = false;
        } catch {
            secondLockReverted = true;
        }

        // Assert the general rule as logical implication: if settle succeeded and this contract gained exactly 2 ether,
        // then c's balance decreased by exactly 2 ether and the second lock must succeed (meaning stored guess was cleared).
        // Encode implication A => B as (!A) || B.
        bool settlePaidOut = (settleReverted == false) && (afterSettleThis == afterLockThis + 2 ether);
        bool cLostTwo = (afterLockCbal == afterSettleCbal + 2 ether);
        bool ruleHolds = (!settlePaidOut) || (cLostTwo && (secondLockReverted == false));

        assert(ruleHolds);
    }

    receive() external payable {}
}
